// Builds the subject and the HTML message of the review request. All customer text is HTML-escaped.
const t = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
const message = `<b>A support ticket needs a sentiment review.</b><br><br>`
  + `Ticket ID: <b>${esc(t.ticketId)}</b><br>`
  + `Customer: ${esc(t.customerName)}<br>`
  + `Department: <b>${esc(t.department)}</b><br>`
  + `AI sentiment: <b>${esc(t.sentimentAi)}</b><br>`
  + `Received: ${esc(t.receivedAt)}<br><br>`
  + `<b>Ticket text</b><br>${esc(t.ticketText)}<br><br>`
  + `Open the review form, choose the sentiment category (the same value confirms the AI category, another value changes it) and submit.`;
return [{ json: { ...t, reviewSubject: `[Review needed] ${t.ticketId} - AI: ${t.sentimentAi} / ${t.department}`, reviewMessage: message } }];
